select tablename, rowsecurity from pg_tables where schemaname = 'public' and tablename in ('tenants', 'import_jobs', 'export_jobs', 'mappings', 'roles', 'user_roles', 'specialties', 'groups', 'subgroups', 'semesters', 'disciplines', 'curriculum', 'buildings', 'rooms', 'teachers', 'teacher_preferences', 'schedules', 'schedule_versions', 'lessons', 'conflicts', 'constraints', 'published_schedules', 'notifications', 'subscriptions', 'workload_reports', 'teacher_loads', 'group_loads', 'audit_events', 'change_logs') order by tablename;